class NomTipoEntrada extends BaseNomTipoEntrada {

    /**
     * Obtener todos los tipos de entrada.
     * 
     * @return array    Listado de los datos de tipos de entrada.
     */
    public static function obtenerTodosTiposEntrada() {

        //Devolviendo el listado de los tipos de entrada en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomTipoEntrada')
                ->fetchArray();
    }

    /**
     * Obtener los tipos de entrada dado un array de identificadores.
     * 
     * @param array $id         Identificadores de tipos de entrada.
     *
     * @return array    Listado de los datos de tipos de entrada.
     */
    public static function obtenerTiposEntradaDadoArrayIds($id) {

        //Devolviendo el listado de los tipos de entrada en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomTipoEntrada')
                ->whereIn('idtipoentrada', $id)
                ->fetchArray();
    }
}